"""Build an offline review gallery from actual Godot-exported geometry and original atlases."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/remaining-assets';OUT.mkdir(exist_ok=True)
m=json.loads((ROOT/'game/assets/production/motions/catalog.json').read_text());g=json.loads((ROOT/'game/tests/asset_production/remaining-previews.json').read_text());icons=json.loads((ROOT/'game/assets/production/icons/catalog.json').read_text())
# Every preview references real files; no synthetic replacement illustrations.
items=[]
for x in m['entries']:items.append({**x,'group':'motions'})
for x in g:
 catalog=json.loads((ROOT/('game/assets/production/'+x['group']+'/catalog.json')).read_text());row=next(e for e in catalog if e['id']==x['id']);items.append({**row,**x})
for x in icons:items.append({**x,'group':'icons'})
(OUT/'data.js').write_text('window.REMAINING_ASSETS='+json.dumps(items,ensure_ascii=False,separators=(',',':'))+';\n')
(OUT/'index.html').write_text('''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>전체 잔여 애셋 · 제작 검토</title><link rel="stylesheet" href="gallery.css"><header><h1>전체 잔여 애셋 · 1차 제작 검토</h1><p>동작1,562 + 첫 승리 보조1 · 소품112 · UI36 · 이벤트14 · 상태변형4 · 아이콘85(기존49 포함)</p><p>실제 원본 아틀라스와 Godot 장면에서 추출한 형상을 표시합니다. 생성 프레임의 방향·발 원점·셀 경계와 최종 미술은 검수 대상입니다. 플레이 빌드 연결 완료를 뜻하지 않습니다.</p><a href="../field-layouts/index.html">필드29 배치 보기</a> · <a href="../asset-handoff-2026-11-03.md">제작 인수인계</a><div><label>분류 <select id="group"><option value="motions">동작 클립</option><option value="props">소품</option><option value="ui">UI</option><option value="events">이벤트 연출</option><option value="world_states">지역 상태</option><option value="icons">아이템 아이콘</option></select></label><input id="search" aria-label="이름 또는 ID 검색" placeholder="이름 또는 ID 검색"><button id="theme">밝은/어두운 배경</button><button id="pause">일시 정지</button><label>3D 회전 <input id="angle" type="range" min="0" max="6.28" step=".05" value=".7"></label></div><p id="count" aria-live="polite"></p><button id="prev">이전</button><button id="next">다음</button></header><main id="cards"></main><dialog id="large"><button id="close">닫기</button><h2 id="detail-title"></h2><canvas width="900" height="700" id="detail-canvas"></canvas><p id="detail-notes"></p></dialog><script src="data.js"></script><script src="gallery.js"></script></html>''')
(OUT/'gallery.css').write_text('''body{background:#18282f;color:#eee6d6;font:15px system-ui;margin:24px}a{color:#edcf90}header{max-width:1100px}h1{font-size:28px}input,select,button{font:inherit;padding:8px;margin:6px}main{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:16px}article{background:#2a3e47;padding:14px;min-width:0}article canvas{width:100%;height:220px;background:#203039;cursor:zoom-in;image-rendering:pixelated}h2{font-size:17px;overflow-wrap:anywhere}small{display:block;overflow-wrap:anywhere;color:#c0c9c9}article p{font-size:13px}.light article,.light article canvas{background:#eee5d3;color:#252b30}.light small{color:#465058}.light article a{color:#365c6c}dialog{background:#1b2c34;color:#eee;border:2px solid #aa8b52;max-width:95vw}dialog canvas{max-width:85vw;max-height:70vh}button:disabled{opacity:.35}''')
print('Gallery entries',len(items))
